package com.bank.monitor.event;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class EventSource {
    private final List<SettlementListener> listeners = new CopyOnWriteArrayList<>();

    public void registerListener(SettlementListener l) { listeners.add(l); }

    public void fire(String tradeId, BigDecimal amount) {
        for (SettlementListener l : listeners) l.onSettled(tradeId, amount);
    }
}
