package com.bank.monitor;

import com.bank.monitor.event.EventSource;
import com.bank.monitor.event.SettlementListener;
import java.math.BigDecimal;
import java.util.logging.Logger;

// BROKEN: 'this' escapes before the constructor finishes.
public class LeakyMonitor implements SettlementListener {
    private static final Logger log = Logger.getLogger(LeakyMonitor.class.getName());
    private final String bankName;
    private final BigDecimal threshold;

    public LeakyMonitor(EventSource source) {
        // DANGER: registering 'this' now — a callback can run before the
        // two fields below are assigned.
        source.registerListener(this);
        this.bankName = "National Bank of India";
        this.threshold = new BigDecimal("1000000");
    }

    @Override
    public void onSettled(String tradeId, BigDecimal amount) {
        // bankName/threshold may still be null/0 if callback races construction
        log.info(() -> "[" + bankName + "] trade " + tradeId + " amount " + amount
                + " big=" + (threshold != null && amount.compareTo(threshold) > 0));
    }
}
