package com.bank.monitor;

import com.bank.monitor.event.EventSource;
import com.bank.monitor.event.SettlementListener;
import java.math.BigDecimal;
import java.util.logging.Logger;

// FIXED: private constructor + static factory. 'this' never escapes.
public class SafeSettlementMonitor {
    private static final Logger log = Logger.getLogger(SafeSettlementMonitor.class.getName());
    private final String bankName;
    private final BigDecimal threshold;
    private final SettlementListener listener;   // inner listener, not 'this'

    private SafeSettlementMonitor() {
        this.bankName = "National Bank of India";
        this.threshold = new BigDecimal("1000000");
        this.listener = this::handle;            // bound only to this object's method
    }

    // Static factory: build FULLY, then register.
    public static SafeSettlementMonitor create(EventSource source) {
        SafeSettlementMonitor monitor = new SafeSettlementMonitor();  // fully built here
        source.registerListener(monitor.listener);                    // safe publish now
        return monitor;
    }

    private void handle(String tradeId, BigDecimal amount) {
        boolean big = amount.compareTo(threshold) > 0;
        log.info(() -> "[" + bankName + "] trade " + tradeId + " amount " + amount + " big=" + big);
    }
}
